#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <climits>

using namespace std;

class mcf_graph_int_cost {
public:
    struct _edge {
        int to;
        int rev;
        long long cap;
        long long cost;
        _edge(int to, int rev, long long cap, long long cost)
            : to(to), rev(rev), cap(cap), cost(cost) {}
    };

    int n;
    vector<vector<_edge>> g;
    vector<pair<int, int>> pos;
    vector<long long> dual, dist;
    vector<int> pv, pe;
    vector<bool> vis;

    mcf_graph_int_cost(int n) : n(n), g(n) {}

    int add_edge(int from, int to, long long cap, long long cost) {
        int m = (int)pos.size();
        pos.emplace_back(from, (int)g[from].size());
        g[from].emplace_back(to, (int)g[to].size(), cap, cost);
        g[to].emplace_back(from, (int)g[from].size() - 1, 0, -cost);
        return m;
    }

    class edge {
    public:
        int from_;
        int to;
        long long cap;
        long long flow;
        long long cost;
        edge(int from_, int to, long long cap, long long flow, long long cost)
            : from_(from_), to(to), cap(cap), flow(flow), cost(cost) {}
    };

    edge get_edge(int i) {
        auto& e = g[pos[i].first][pos[i].second];
        auto& re = g[e.to][e.rev];
        return edge(pos[i].first, e.to, e.cap + re.cap, re.cap, e.cost);
    }

    vector<edge> edges() {
        vector<edge> ret;
        for (size_t i = 0; i < pos.size(); ++i) {
            auto& e = g[pos[i].first][pos[i].second];
            auto& re = g[e.to][e.rev];
            ret.emplace_back(pos[i].first, e.to, e.cap + re.cap, re.cap, e.cost);
        }
        return ret;
    }

    bool _dual_ref(int s, int t) {
        dist.assign(n, LLONG_MAX);
        pv.assign(n, -1);
        pe.assign(n, -1);
        vis.assign(n, false);
        priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> que;

        dist[s] = 0;
        que.emplace(0, s);
        while (!que.empty()) {
            auto [d, v] = que.top(); que.pop();
            if (vis[v]) continue;
            vis[v] = true;
            if (v == t) break;
            for (int i = 0; i < (int)g[v].size(); ++i) {
                auto& e = g[v][i];
                if (vis[e.to] || e.cap == 0) continue;
                long long cost = e.cost - dual[e.to] + dual[v];
                if (dist[e.to] > dist[v] + cost) {
                    dist[e.to] = dist[v] + cost;
                    pv[e.to] = v;
                    pe[e.to] = i;
                    que.emplace(dist[e.to], e.to);
                }
            }
        }
        if (!vis[t]) return false;
        for (int v = 0; v < n; ++v) {
            if (vis[v]) {
                dual[v] -= dist[t] - dist[v];
            }
        }
        return true;
    }

    vector<pair<long long, long long>> slope(int s, int t, long long flow_limit = LLONG_MAX) {
        dual.assign(n, 0);
        dist.assign(n, LLONG_MAX);
        pv.assign(n, -1);
        pe.assign(n, -1);
        vis.assign(n, false);
        long long flow = 0;
        long long cost = 0;
        long long prev_cost = -1;
        vector<pair<long long, long long>> result;
        result.emplace_back(flow, cost);
        while (flow < flow_limit) {
            if (!_dual_ref(s, t)) break;
            long long c = flow_limit - flow;
            int v = t;
            while (v != s) {
                c = min(c, g[pv[v]][pe[v]].cap);
                v = pv[v];
            }
            v = t;
            while (v != s) {
                auto& e = g[pv[v]][pe[v]];
                e.cap -= c;
                g[v][e.rev].cap += c;
                v = pv[v];
            }
            long long d = -dual[s];
            flow += c;
            cost += c * d;
            if (prev_cost == d) {
                if (!result.empty()) result.pop_back();
            }
            result.emplace_back(flow, cost);
            prev_cost = cost;
        }
        return result;
    }

    long long flow(int s, int t, long long flow_limit = LLONG_MAX) {
        return slope(s, t, flow_limit).back().second;
    }
};

