int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> rock1(3), sci1(3), paper1(3);
    for (int i = 0; i < 3; i++) cin >> rock1[i];
    for (int i = 0; i < 3; i++) cin >> sci1[i];
    for (int i = 0; i < 3; i++) cin >> paper1[i];

    vector<int> rock2(3), sci2(3), paper2(3);
    for (int i = 0; i < 3; i++) cin >> rock2[i];
    for (int i = 0; i < 3; i++) cin >> sci2[i];
    for (int i = 0; i < 3; i++) cin >> paper2[i];

    auto maximum = [&]() {
        int ans = min(rock1[0], sci2[1]) + min(sci1[1], paper2[2]) + min(paper1[2], rock2[0]);
        return ans;
    };

    auto match = [](int a, int b) {
        if (a == b) return 0;
        if ((a == 1 && b == 2) || (a == 2 && b == 3) || (a == 3 && b == 1))
            return 1;
        else
            return -1;
    };

    auto give = [&](vector<vector<int>> &l1, vector<vector<int>> &l2) {
        int ans = 0;
        int curr1 = 0, curr2 = 0;
        vector<int> stack1, stack2;
        while (!l1.empty() || !l2.empty()) {
            if (curr1 == 0 && !l1.empty()) {
                auto temp = l1.back(); l1.pop_back();
                curr1 = temp[0];
            }
            if (curr2 == 0 && !l2.empty()) {
                auto temp = l2.back(); l2.pop_back();
                curr2 = temp[0];
            }
            if (curr1 == 0 || curr2 == 0) break;
            int min_val = min(curr1, curr2);
            int res = match(l1.back()[1], l2.back()[1]);
            ans += max(0, min_val * res);
            if (curr1 < curr2) {
                curr2 -= curr1;
                curr1 = 0;
            } else if (curr1 > curr2) {
                curr1 -= curr2;
                curr2 = 0;
            } else {
                curr1 = 0;
                curr2 = 0;
            }
        }
        return ans;
    };

    auto minimum = [&]() {
        vector<vector<int>> l1, l2;
        vector<vector<int>> base = {{rock1[0], 1}, {sci1[1], 2}, {paper1[2], 3}};
        do {
            l1 = base;
            int min_ans = INT_MAX;
            vector<vector<int>> base2 = {{rock2[0], 1}, {sci2[1], 2}, {paper2[2], 3}};
            do {
                l2 = base2;
                min_ans = min(min_ans, give(l1, l2));
            } while (next_permutation(base2.begin(), base2.end()));
            return min_ans;
        } while (next_permutation(base.begin(), base.end()));
        return INT_MAX;
    };

    cout << minimum() << " " << maximum() << "\n";

    return 0;
}

#include <iostream>
#include <vector>
