int getWonMaxFast(std::vector<int>& inputA, std::vector<int>& inputB) {
    std::vector<int> wins(3, 0);
    for (int i = 0; i < 3; ++i) {
        int good = (i + 1) % 3;
        wins[i] = std::min(inputA[i], inputB[good]);
        inputA[i] -= wins[i];
        inputB[good] -= wins[i];
    }
    return std::accumulate(wins.begin(), wins.end(), 0);
}

int getLostMaxFast(std::vector<int> inputA, std::vector<int> inputB) {
    std::vector<std::vector<int>> waysToLose = {
        {0, 2}, {1, 0}, {2, 1},
        {0, 0}, {1, 1}, {2, 2}
    };

    std::vector<std::vector<int>> allWaysToLosePermutations;
    std::sort(waysToLose.begin(), waysToLose.end());
    do {
        allWaysToLosePermutations.push_back(waysToLose);
    } while (std::next_permutation(waysToLose.begin(), waysToLose.end()));

    int maxLost = 0;

    for (const auto& permutation : allWaysToLosePermutations) {
        std::vector<int> losts(3, 0);
        std::vector<int> inputACopy = inputA;
        std::vector<int> inputBCopy = inputB;

        for (const auto& wayToLose : permutation) {
            int lost_add = std::min(inputACopy[wayToLose[0]], inputBCopy[wayToLose[1]]);
            inputACopy[wayToLose[0]] -= lost_add;
            inputBCopy[wayToLose[1]] -= lost_add;
            losts[wayToLose[0]] += lost_add;
        }

        int lostSum = std::accumulate(losts.begin(), losts.end(), 0);
        if (lostSum > maxLost) {
            maxLost = lostSum;
        }
    }
    return maxLost;
}

int main() {
    int n;
    std::cin >> n;
    std::vector<int> inputA(3), inputB(3);
    for (int i = 0; i < 3; ++i) {
        std::cin >> inputA[i];
    }
    for (int i = 0; i < 3; ++i) {
        std::cin >> inputB[i];
    }
    std::vector<int> inputA2 = inputA;
    std::vector<int> inputB2 = inputB;

    int lost = n - getLostMaxFast(inputA2, inputB2);
    int won = getWonMaxFast(inputA, inputB);
    std::cout << lost << " " << won << std::endl;
    return 0;
}

