int main() {
    int turnNum;
    std::cin >> turnNum;
    std::vector<int> aliceChoices(turnNum);
    std::vector<int> bobChoices(turnNum);

    for (int i = 0; i < turnNum; ++i) {
        std::cin >> aliceChoices[i];
    }
    for (int i = 0; i < turnNum; ++i) {
        std::cin >> bobChoices[i];
    }

    // Rotate bobChoices by one position
    int first_bob_choice = bobChoices[0];
    for (int i = 0; i < turnNum - 1; ++i) {
        bobChoices[i] = bobChoices[i + 1];
    }
    bobChoices[turnNum - 1] = first_bob_choice;

    int minWin = 0, maxWin = 0;

    // Calculate maximum number of rounds Alice can win
    for (int i = 0; i < turnNum; ++i) {
        maxWin += std::min(aliceChoices[i], bobChoices[i]);
    }

    // Calculate minimum number of rounds Alice can win
    int maximum_bob = *std::max_element(bobChoices.begin(), bobChoices.end());
    for (int i = 0; i < turnNum; ++i) {
        if (bobChoices[i] == maximum_bob && bobChoices[i] + aliceChoices[i] > minWin) {
            minWin = bobChoices[i] + aliceChoices[i];
        }
    }
    int maximum_alice = *std::max_element(aliceChoices.begin(), aliceChoices.end());
    for (int i = 0; i < turnNum; ++i) {
        if (aliceChoices[i] == maximum_alice && aliceChoices[i] + bobChoices[i] > minWin) {
            minWin = aliceChoices[i] + bobChoices[i];
        }
    }
    if (minWin > turnNum) {
        minWin -= turnNum;
    } else {
        minWin = 0;
    }

    std::cout << minWin << " " << maxWin << std::endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    int round;
    std::cin >> round;

    std::vector<int> firstperson(3);
    std::vector<int> secondperson(3);

    for (int i = 0; i < 3; ++i) {
        std::cin >> firstperson[i];
    }
    for (int i = 0; i < 3; ++i) {
        std::cin >> secondperson[i];
    }

    int solve(int round, std::vector<int>& firstperson, std::vector<int>& secondperson) {
        int win = 0;
        // Append first element to the end for circular comparison
        secondperson.push_back(secondperson[0]);

        for (int i = 0; i < 3; ++i) {
            int findless;
            if (firstperson[i] <= secondperson[i + 1]) {
                findless = firstperson[i];
            } else {
                findless = secondperson[i + 1];
            }
            win += findless;
        }

        // Remove the appended element
        secondperson.pop_back();

        // Insert third element at the beginning
        secondperson.insert(secondperson.begin(), secondperson[2]);

        for (int i = 0; i < 3; ++i) {
            if (firstperson[i] > 0) {
                int diff = std::min(firstperson[i], secondperson[i]);
                firstperson[i] -= diff;
                secondperson[i] -= diff;

                if (firstperson[i] > 0) {
                    int diff2 = std::min(firstperson[i], secondperson[i + 1]);
                    firstperson[i] -= diff2;
                    secondperson[i + 1] -= diff2;
                }
            }
        }

        int total_firstperson = firstperson[0] + firstperson[1] + firstperson[2];
        std::cout << total_firstperson << " " << win << std::endl;
        return 0;
    }

    solve(round, firstperson, secondperson);
    return 0;
}

