long long modpow(long long a, long long p, long long MOD) {
    long long ans = 1;
    while (p) {
        if (p & 1) {
            ans = (ans * a) % MOD;
        }
        p >>= 1;
        a = (a * a) % MOD;
    }
    return ans;
}

