    auto LIST = [&](int N = -1) {
        vector<int> res;
        if (N == -1) {
            string s; getline(cin, s);
            stringstream ss(s);
            int x;
            while (ss >> x) res.push_back(x);
        } else {
            for (int i = 0; i < N; i++) {
                int x; cin >> x;
                res.push_back(x);
            }
            cin.ignore();
        }
        return res;
    };

