        // s to Alice
        add_edge(s, i, N);
        // Bob to t
        add_edge(M + i, t, B[i]);
        // draw
        add_edge(i, M + i, A[i]);
        // Alice lose
        add_edge(i, M + ((i - 1 + M) % M), A[i]);
    }

