    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    // Generate primes up to 6000
    for (int p = 2; p < 6000; p++) {
        bool is_prime = true;
        for (int p2 : primes) {
            if (p2 * p2 > p) break;
            if (p % p2 == 0) {
                is_prime = false;
                break;
            }
        }
        if (is_prime) {
            primes.push_back(p);
        }
    }

    // Function to factorize n into its prime factors
    auto factor = [&](long long n) {
        unordered_map<long long, int> d;
        for (int p : primes) {
            if ((long long)p * p > n) break;
            if (n % p == 0) {
                int c = 0;
                while (n % p == 0) {
                    n /= p;
                    c++;
                }
                d[p] = c;
            }
        }
        if (n > 1) {
            d[n] = 1;
        }
        return d;
    };

    // Function to generate all factors of n
    auto factors = [&](long long n) {
        auto d = factor(n);
        vector<long long> answer = {1};
        for (auto &p_c : d) {
            long long p = p_c.first;
            int c = p_c.second;
            vector<long long> a2;
            for (auto &x : answer) {
                long long p_pow = 1;
                for (int i = 0; i <= c; i++) {
                    a2.push_back(x * p_pow);
                    p_pow *= p;
                }
            }
            answer = a2;
        }
        return answer;
    };

    int n, m;
    cin >> n >> m;

    vector<long long> f_dict(n + 1, 0);
    f_dict[0] = 0;
    if (n >= 1) f_dict[1] = 1;
    if (n >= 2) f_dict[2] = 2;

    for (int i = 3; i <= n; i++) {
        f_dict[i] = 2 * f_dict[i - 1];
        for (auto &x : factors(i)) {
            if (2 <= x && x <= i) {
                long long quotient1 = i / x;
                long long quotient2 = (i - 1) / x;
                long long val = f_dict[quotient1] - f_dict[quotient2];
                f_dict[i] += val;
            }
        }
        f_dict[i] %= m;
    }

    cout << f_dict[n] % m << "\n";

    return 0;
}

