#include <iostream>
#include <vector>
#include <set>
#include <cmath>

using namespace std;

bool is_good(const vector<int>& f, int p, int k) {
    for (int i = 0; i < p; ++i) {
        if (f[(k * i) % p] != (k * f[i]) % p) {
            return false;
        }
    }
    return true;
}

int gen(vector<int>& f, int p, int k, int i) {
    if (i == p) {
        return is_good(f, p, k) ? 1 : 0;
    } else {
        int ans = 0;
        for (int j = 0; j < p; ++j) {
            f.push_back(j);
            ans += gen(f, p, k, i + 1);
            f.pop_back();
        }
        return ans;
    }
}

long long solve(int p, int k) {
    long long num = 0;
    set<int> used;
    for (int j = 0; j < p; ++j) {
        if (used.find(j) == used.end()) {
            num += 1;
        }
        int i = j;
        while (used.find(i) == used.end()) {
            used.insert(i);
            i = (i * k) % p;
        }
    }
    const long long MOD = 1000000007;
    long long exponent = num - (k != 1 ? 1 : 0);
    long long result = 1;
    long long base = p % MOD;
    long long exp = exponent;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % MOD;
        }
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

