#include <iostream>
#include <vector>
using namespace std;

long long solve(int n, int mod) {
    if (n <= 3) {
        return 0;
    } else {
        long long last_ans = 17;
        long long ans = 17;
        int size = (n - 1) * (n - 2) / 2 + 1;
        int inv = 1;
        vector<vector<long long>> record(2, vector<long long>(size + 1, 0));
        record[0][0] = 1;
        record[0][1] = 2;
        record[0][2] = 2;
        record[0][3] = 1;
        for (int m = 4; m < n; ++m) {
            int tp_size = m * (m - 1) / 2;
            ans = (long long)(m + 1) * last_ans;
            long long tp = 0;
            for (int i = 0; i < m; ++i) {
                tp += record[inv ^ 1][i];
                record[inv][i] = tp % mod;
            }
            for (int i = m; i <= tp_size / 2; ++i) {
                tp += record[inv ^ 1][i];
                tp -= record[inv ^ 1][i - m];
                record[inv][i] = tp % mod;
            }
            for (int i = 0; i <= tp_size / 2; ++i) {
                record[inv][tp_size - i] = record[inv][i];
            }
            long long total = 0;
            for (int i = 0; i < tp_size; ++i) {
                tp = 0;
                int start_j = max(1, -tp_size + i + m + 2);
                for (int j = start_j; j <= m; ++j) {
                    tp += j * record[inv][m + 2 - j + i];
                }
                total += record[inv][i];
                total %= mod;
                tp %= mod;
                ans += (tp * total) % mod;
                ans %= mod;
            }
            last_ans = ans;
            inv ^= 1;
        }
        return ans % mod;
    }
}

int main() {
    int n, mod;
    cin >> n >> mod;
    cout << solve(n, mod) << "\n";
    return 0;
}

